output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to take the entrance cart before doing the shop.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "entry_cart_taken": {
          "pre": {
            "and": [
              "at_entry_cart",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_taken"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Loose hand-carrying of groceries is prohibited; groceries should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper may pick up shelf items only while currently holding the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "return_cart_before_exit",
    "text": "After taking a cart, the shopper is obliged to park it in the designated return bay at cell (0,1) before leaving the store.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "cart_return_bay_agent": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "holding_cart"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay_agent",
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "Leaving a cart anywhere other than the designated return bay at (0,1) is prohibited.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "away_from_return_bay": {
          "not": "at_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_cart_in_checkout_zone",
    "text": "Carts are prohibited in the eastern checkout and exit zone, so the shopper must continue to the exit without the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "checkout_exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_exit_zone": {
          "and": [
            "holding_cart",
            "checkout_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_exit_zone"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once a cart has been parked in the return bay, picking it up again from that bay is prohibited.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "at_return_bay",
              "cart_parked_in_return_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  },
  {
    "id": "item_pickup_only_at_shelf_fronts",
    "text": "Item-pickup interactions are permitted only at recognized shelf-front pickup cells, distinguishing them from cart pickup or cart return interactions.",
    "abstraction": {
      "state_properties": {
        "approved_item_pickup_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)",
            "at(3,2)",
            "at(3,4)",
            "at(5,2)",
            "at(5,4)",
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "not_approved_item_pickup_cell": {
          "not": "approved_item_pickup_cell"
        }
      },
      "events": {
        "unapproved_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_approved_item_pickup_cell"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "unapproved_item_pickup"
    }
  }
]
